"""HTTP fetch implementation for the fixed local diagnostic manifest."""
import json
from pathlib import Path
from urllib.parse import urljoin

import requests

MANIFEST = Path(__file__).resolve().parent.parent / "diagnostics.json"
REDIRECT_STATUSES = (301, 302, 303, 307, 308)
MAX_REDIRECTS = 5
TIMEOUT = 10.0


def manifest_urls() -> set[str]:
    return set(json.loads(MANIFEST.read_text()))


def fetch(url: str) -> str:
    allowed = manifest_urls()
    if url not in allowed:
        raise ValueError(f"URL is not listed in {MANIFEST.name}: {url}")

    target = url
    for _ in range(MAX_REDIRECTS + 1):
        response = requests.get(target, timeout=TIMEOUT, allow_redirects=False)
        if response.status_code not in REDIRECT_STATUSES:
            response.raise_for_status()
            return response.content.decode("utf-8")

        location = response.headers.get("Location")
        if not location:
            raise ValueError(f"Redirect from {target} has no Location header")
        target = urljoin(target, location)
        if target not in allowed:
            raise ValueError(f"Redirect leaves {MANIFEST.name}: {target}")

    raise ValueError(f"More than {MAX_REDIRECTS} redirects from {url}")
PY
